#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# First npm publish of packages that have never been published, so trusted
# publishing (release.yml) can take over. Run from the repository root:
#   bash scripts/first-publish.sh
# Packages are built from the latest version-packages commit on trunk
# (override with PUBLISH_REF=<commit>), so each version matches its changelog
# and its `workspace:^` dependency on core resolves to a core already on npm.

TOTAL_STAGES=9

REPO="thomasfosterau/effect-connect"
NPM_USER="thomasfosterau"
WORKDIR=""
NEW_NAMES=()    # package names never published
NEW_DIRS=()     # their directories, relative to the repo root
NEW_VERSIONS=() # the version each will get
TARBALLS=()     # packed tarballs, in the same order
PUBLISHED=()    # name@version published this run

cleanup() {
  if [[ -n "$WORKDIR" && -d "$WORKDIR" ]]; then
    git worktree remove --force "$WORKDIR" >/dev/null 2>&1 || rm -rf "$WORKDIR"
  fi
}
trap cleanup EXIT

# json_field FILE_CONTENT KEY: the first top-level "KEY": "value" string.
json_field() {
  printf '%s' "$1" | grep -m1 -E "^  \"$2\": *\"" | sed -E "s/^  \"$2\": *\"([^\"]*)\".*/\1/"
}

# on_npm SPEC: 0 if the registry has it, 1 if it's a 404, 2 on any other error.
on_npm() {
  local out
  if out=$(vp pm view "$1" version 2>&1) && [[ -n "$out" ]]; then return 0; fi
  if [[ "$out" == *E404* || -z "$out" ]]; then return 1; fi
  printf '%s\n' "$out" | tail -n3 >&2
  return 2
}

die() { printf '\n  %s✗ %s%s\n\n' "$RED" "$1" "$RESET"; exit 1; }

banner "First npm publish of new effect-connect packages"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check the checkout and find the new packages"
[[ -f pnpm-workspace.yaml && -d packages ]] || die "Run this from the effect-connect repository root."
for bin in git vp; do
  command -v "$bin" >/dev/null 2>&1 || die "$bin isn't on PATH."
done
say "Fetching trunk…"
git fetch --quiet origin trunk || die "git fetch origin trunk failed."

PUBLISH_REF="${PUBLISH_REF:-$(git log origin/trunk -n1 --format=%H \
  --grep='changeset-release/trunk' --grep='^chore: version packages')}"
[[ -n "$PUBLISH_REF" ]] || die "Couldn't find a version-packages commit on origin/trunk; set PUBLISH_REF."
say "Building from ${BOLD}$(git log -1 --format='%h %s' "$PUBLISH_REF")${RESET}"
note "(the latest version-packages merge on trunk, so each version matches its changelog)"
printf '\n'

for manifest in $(git ls-tree --name-only "$PUBLISH_REF" packages/ | sed 's|$|/package.json|'); do
  content=$(git show "$PUBLISH_REF:$manifest" 2>/dev/null) || continue
  printf '%s' "$content" | grep -qE '^  "private": *true' && continue
  name=$(json_field "$content" name)
  version=$(json_field "$content" version)
  set +e; on_npm "$name"; rc=$?; set -e
  case $rc in
    0) note "  $name is already on npm; release.yml handles it" ;;
    1) NEW_NAMES+=("$name"); NEW_DIRS+=("$(dirname "$manifest")"); NEW_VERSIONS+=("$version")
       step "${BOLD}$name${RESET} ${version}: never published" ;;
    *) die "Couldn't reach the npm registry for $name." ;;
  esac
done
printf '\n'
if (( ${#NEW_NAMES[@]} == 0 )); then
  say "${GREEN}Every public package is already on npm. Nothing to do.${RESET}"
  exit 0
fi
warn "Don't merge the \"chore: version packages\" PR until stage 8 says so."
pause "Continue with these ${#NEW_NAMES[@]} package(s)?"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Build and pack the release commit"
say "This builds in a throwaway worktree, so your checkout isn't touched."
WORKDIR=$(mktemp -d "${TMPDIR:-/tmp}/effect-connect-first-publish.XXXXXX")
rmdir "$WORKDIR"
git worktree add --quiet --detach "$WORKDIR" "$PUBLISH_REF"
mkdir -p "$WORKDIR/.tarballs"
(
  cd "$WORKDIR"
  vp install --frozen-lockfile
  vp run -r build
) || die "Install or build failed in $WORKDIR."
for i in "${!NEW_NAMES[@]}"; do
  (cd "$WORKDIR/${NEW_DIRS[$i]}" && vp pm pack --pack-destination "$WORKDIR/.tarballs" >/dev/null) \
    || die "vp pm pack failed for ${NEW_NAMES[$i]}."
  slug=$(printf '%s' "${NEW_NAMES[$i]}" | sed -e 's|^@||' -e 's|/|-|')
  TARBALLS+=("$WORKDIR/.tarballs/$slug-${NEW_VERSIONS[$i]}.tgz")
  [[ -f "${TARBALLS[$i]}" ]] || die "Expected tarball ${TARBALLS[$i]} is missing."
done
printf '\n'
say "${GREEN}✓ Built and packed ${#TARBALLS[@]} tarball(s).${RESET}"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Review what will be published"
say "These exact tarballs are what stage 5 publishes."
for i in "${!NEW_NAMES[@]}"; do
  printf '\n  %s%s@%s%s\n' "$BOLD" "${NEW_NAMES[$i]}" "${NEW_VERSIONS[$i]}" "$RESET"
  tar -tzf "${TARBALLS[$i]}" | sed 's|^package/|    |' | sort
  tar -xOzf "${TARBALLS[$i]}" package/package.json \
    | sed -nE '/^  "(dependencies|peerDependencies)": \{/,/^  \}/p' | sed 's/^/    /'
done
printf '\n'
step "Check: dist/ is present, dependencies hold real ranges (no workspace: or catalog:),"
step "and the core range points at a version already on npm."
confirm "Does that look right?" || die "Stopped before publishing; nothing was published."

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Log in to npm as $NPM_USER"
current=$(vp pm whoami 2>/dev/null || true)
if [[ "$current" == "$NPM_USER" ]]; then
  say "${GREEN}✓ Already logged in as $NPM_USER.${RESET}"
else
  [[ -n "$current" ]] && warn "Logged in as '$current', not $NPM_USER."
  say "npm opens a browser to sign in; finish it there, including 2FA."
  vp pm login || die "vp pm login failed."
  current=$(vp pm whoami 2>/dev/null || true)
  [[ "$current" == "$NPM_USER" ]] || die "vp pm whoami says '$current', not $NPM_USER."
  say "${GREEN}✓ Logged in as $NPM_USER.${RESET}"
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Publish each package (irreversible)"
warn "A published version can't be reused, even after unpublishing."
for i in "${!NEW_NAMES[@]}"; do
  spec="${NEW_NAMES[$i]}@${NEW_VERSIONS[$i]}"
  printf '\n'
  if on_npm "$spec" 2>/dev/null; then
    note "  $spec is already on npm; skipping"
    continue
  fi
  confirm "Publish $spec now?" || { SKIPPED+=("publish $spec"); continue; }
  while :; do
    otp=""
    printf '  %sOne-time password from your authenticator%s %s(Enter if npm doesn'"'"'t ask)%s ' \
      "$BOLD" "$RESET" "$DIM" "$RESET"
    read -r otp || true
    args=(--access public --no-git-checks)
    [[ -n "$otp" ]] && args+=(--otp "$otp")
    if (cd "$WORKDIR" && vp pm publish "${TARBALLS[$i]}" "${args[@]}" -- --ignore-scripts); then
      PUBLISHED+=("$spec")
      say "${GREEN}✓ published $spec${RESET}"
      break
    fi
    confirm "Publishing $spec failed. Try again (for example with a fresh code)?" \
      || { SKIPPED+=("publish $spec"); break; }
  done
done
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Check the registry"
missing=0
for i in "${!NEW_NAMES[@]}"; do
  spec="${NEW_NAMES[$i]}@${NEW_VERSIONS[$i]}"
  if on_npm "$spec" 2>/dev/null; then
    step "${GREEN}✓${RESET} $spec is on npm"
  else
    step "${RED}✗${RESET} $spec isn't on npm yet"; missing=1
  fi
done
printf '\n'
if (( missing )); then
  warn "The registry can lag a minute. Re-run this script later: it skips what's done."
  warn "Don't add trusted publishers or merge the version PR until every package is on npm."
  exit 1
fi
say "Logging out, so the token npm login created doesn't stay on this machine."
vp pm logout >/dev/null 2>&1 || SKIPPED+=("vp pm logout")
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Add the trusted publishers"
note "npm expires a new trusted publisher that hasn't published within 2 days,"
note "so do this only when you're ready to merge the version PR in stage 8."
for name in "${NEW_NAMES[@]}"; do
  printf '\n  %s%s%s\n' "$BOLD" "$name" "$RESET"
  open_url "https://www.npmjs.com/package/$name/access"
  step "Under ${BOLD}Trusted Publisher${RESET}, choose ${BOLD}GitHub Actions${RESET} and fill in:"
  note "      Organization or user:  thomasfosterau"
  note "      Repository:            effect-connect"
  note "      Workflow filename:     release.yml"
  note "      Environment name:      release"
  step "Save (npm may ask for 2FA)."
  step "Optional, same page: Publishing access → \"Require two-factor authentication"
  step "and disallow tokens\" → Update Package Settings. Trusted publishing keeps working."
  pause "Press Enter once $name has its trusted publisher"
done

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Release through GitHub Actions"
open_url "https://github.com/$REPO/pulls?q=is%3Apr+is%3Aopen+%22chore%3A+version+packages%22"
step "If the \"chore: version packages\" PR is open, merge it."
step "If it already merged and its Release run failed, open that run and"
step "choose ${BOLD}Re-run failed jobs${RESET}."
pause "Press Enter once it's merged or re-run"
open_url "https://github.com/$REPO/actions/workflows/release.yml"
step "Open the newest Release run. The ${BOLD}Publish to npm${RESET} job waits on the"
step "${BOLD}release${RESET} environment: Review deployments → release → Approve and deploy."
step "Wait for the run to finish."
confirm "Did the Release run succeed?" \
  || SKIPPED+=("a successful Release run: read the Publish to npm log, fix, and Re-run failed jobs")

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Check every package's latest version"
say "Each package's latest version on npm, against the version on trunk:"
git fetch --quiet origin trunk || true
for manifest in $(git ls-tree --name-only origin/trunk packages/ | sed 's|$|/package.json|'); do
  content=$(git show "origin/trunk:$manifest" 2>/dev/null) || continue
  printf '%s' "$content" | grep -qE '^  "private": *true' && continue
  name=$(json_field "$content" name)
  want=$(json_field "$content" version)
  have=$(vp pm view "$name" version 2>/dev/null || echo "none")
  if [[ "$have" == "$want" ]]; then
    step "${GREEN}✓${RESET} $name $have"
  else
    step "${YELLOW}…${RESET} $name: npm has $have, trunk has $want"
    SKIPPED+=("$name $want isn't on npm yet")
  fi
done
printf '\n'
note "Versions published by the Release run carry provenance; the hand-published"
note "first versions don't, which is expected."
pause "Press Enter for the summary"

finish
if (( ${#PUBLISHED[@]} )); then
  note "published by hand this run: ${PUBLISHED[*]}"
  printf '\n'
fi
